#include "repair_exact_phase.hpp"
#include "repair_detail.hpp"
#include "resident/kernel/world_bundle.hpp"
namespace hanmo::resident {using namespace repair_detail;namespace {
std::shared_ptr<const RepairExactReadLease> read(const RepairExactWorldFactory&f,const WorldBundle&w,const WorldMoment&at){if(!f.read||!f.write)fail("RepairExactWorldFactoryRequired",{},ErrorKind::unsupported_capability);auto lease=take(f.read(w,at));if(!lease)fail("RepairExactReadLeaseRequired",{},ErrorKind::unsupported_capability);const auto&x=lease->bindings().repair;context(x);if(&x.common!=&w.common||compare(now(x),at))fail("RepairExactReadBindingMismatch");return lease;}
std::shared_ptr<RepairExactWriteLease> write(const RepairExactWorldFactory&f,WorldBundle&w,const WorldMoment&at,ExactPhaseWriteContext&writes){if(!f.read||!f.write)fail("RepairExactWorldFactoryRequired",{},ErrorKind::unsupported_capability);auto lease=take(f.write(w,at,writes));if(!lease)fail("RepairExactWriteLeaseRequired",{},ErrorKind::unsupported_capability);const auto b=lease->bindings();writable(b.common,b.items,b.elapsed,b.repair);if(&b.common!=&w.common||compare(now(b.repair.read),at))fail("RepairExactWriteBindingMismatch");return lease;}
std::vector<ExactEventPrediction> predict(const RepairReadContext&x,const WorldMoment&from,const WorldMoment&until){if(compare(from,until)>0||compare(now(x),from))fail("RepairPredictionWindowMismatch");std::vector<ExactEventPrediction>out;for(const auto&row:x.items.repair_jobs.jobs.rows()){const auto&j=row.second;if(j.phase!=RepairJobPhase::working)continue;take(read_original_repair_job(x,j.id));const auto*e=find_fixed_elapsed(x.elapsed,j.action_id);if(!e||!std::holds_alternative<ElapsedRunning>(e->timing))fail("RepairWorkingElapsedRequired",j.id);const auto history=transitions(x,j);validate_elapsed_history(x,j,*e,history);const auto&due=std::get<ElapsedRunning>(e->timing).completion_due_at;if(compare(due,from)<0)fail("UnconsumedRepairCompletion",j.id);take(compare(due,from)==0?validate_fixed_elapsed_at_completion_due(*e,from,x.scale,x.arithmetic_budget):validate_fixed_elapsed_value(*e,from,x.scale,x.arithmetic_budget));if(compare(due,until)<=0)out.push_back({due,ExactStage::action_completions,repair_job_source(j.id),1,history.back().transition_ordinal});}return out;}
}
bool repair_exact_selected(const RepairExactWorldFactory&f)noexcept{return f.read||f.write;}
Status validate_repair_exact_author_selection(const RepairExactWorldFactory&f,const WorldBundle&w){try{auto lease=read(f,w,take(w.actual_phase_moment()));const auto&x=lease->bindings().repair;take(validate_time_scale(x.scale));take(validate_repair_policy_catalog(x.policies,x.common_catalog));return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
Status validate_repair_exact_world(const RepairExactWorldFactory&f,const WorldBundle&w,const WorldMoment&at){try{auto lease=read(f,w,at);return validate_repair_jobs(lease->bindings().repair);}catch(Failure&e){return {false,{},std::move(e.error)};}}
Outcome<std::vector<ExactEventPrediction>> predict_repair_exact_events(const RepairExactWorldFactory&f,const WorldBundle&w,const WorldMoment&from,const WorldMoment&until){try{auto lease=read(f,w,from);return {true,predict(lease->bindings().repair,from,until),{}};}catch(Failure&e){return {false,{},std::move(e.error)};}}
Status provide_repair_exact_interval(const RepairExactWorldFactory&f,WorldBundle&w,const MomentSpan&span,ExactPhaseWriteContext&writes){try{auto lease=write(f,w,span.to,writes);const auto b=lease->bindings();for(const auto&row:b.items.repair_jobs.jobs.rows())if(row.second.phase==RepairJobPhase::working)take(provide_repair_service_interval_in_candidate(b.common,b.items,b.elapsed,b.repair,row.first,span));return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
Outcome<ExactEventApplied> apply_repair_exact_due(const RepairExactWorldFactory&f,WorldBundle&w,const ExactEventPrediction&p,ExactPhaseWriteContext&writes){try{if(p.stage!=ExactStage::action_completions||p.source_schema!=1||!same_source_ref(p.actual_source_basis,repair_job_source(p.actual_source_basis.id)))fail("RepairDueSourceMismatch",p.actual_source_basis.id);auto lease=write(f,w,p.at,writes);const auto b=lease->bindings();const auto pending=predict(b.repair.read,p.at,p.at);bool found=false;for(const auto&v:pending)if(same_source_ref(v.actual_source_basis,p.actual_source_basis)&&v.dependency_revision==p.dependency_revision)found=true;if(!found)fail("StaleRepairDuePrediction",p.actual_source_basis.id);const auto result=take(complete_repair_in_candidate(b.common,b.items,b.elapsed,b.repair,p.actual_source_basis.id));return {true,{repair_completed_source(result),1},{}};}catch(Failure&e){return {false,{},std::move(e.error)};}}
Status validate_repair_exact_applied(const RepairExactWorldFactory&f,const WorldBundle&w,const ExactEventApplied&result){try{if(result.source_schema!=1||!same_source_ref(result.applied_result,repair_completed_source(result.applied_result.id)))fail("RepairAppliedSourceMismatch",result.applied_result.id);auto lease=read(f,w,take(w.actual_phase_moment()));const auto&x=lease->bindings().repair;const auto*r=x.items.repair_jobs.completions.find(result.applied_result.id);const auto*j=r?x.items.repair_jobs.jobs.find(r->job_id):nullptr;if(!j)fail("RepairAppliedCompletionRequired",result.applied_result.id);take(read_actual_repair_completed(x,result.applied_result,j->terms.instance_id));return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
}
